using CivicConnect.Web.Models; namespace CivicConnect.Web.Services; public sealed class TicketService { public List<Ticket> Tickets {get;} = new(){ new(){Id="CC-014",Title="Unable to connect to office Wi-Fi",Category="IT Support",Priority="High",Status="In Progress",Updated="Today, 14:20",Requester="Bernard Small",Assignee="Daniel Jacobs",Description="The office Wi-Fi keeps disconnecting from my laptop. I have restarted the device and forgotten/rejoined the network, but the connection still drops every few minutes."}, new(){Id="CC-013",Title="Air conditioner not working",Category="Facilities",Priority="Medium",Status="Open",Updated="Yesterday",Requester="Bernard Small",Description="The air conditioner in Meeting Room B is not cooling the room."}, new(){Id="CC-012",Title="Request copy of leave policy",Category="HR Request",Priority="Low",Status="Resolved",Updated="12 Sep 2026",Requester="Bernard Small",Assignee="Nadia Peters",Description="Please provide the latest approved employee leave policy document."}, new(){Id="CC-010",Title="New starter system access",Category="IT Support",Priority="High",Status="Open",Updated="9 Sep 2026",Requester="Ayesha Khan",Description="Please create system access for a new staff member starting Monday."} }; public Ticket? Find(string id)=>Tickets.FirstOrDefault(x=>x.Id==id); public string Create(Ticket t){var n=Tickets.Select(x=>int.Parse(x.Id.Split('-')[1])).DefaultIfEmpty(0).Max()+1;t.Id=$"CC-{n:000}";t.Status="Open";t.Updated="Just now";t.Created=DateTime.Now.ToString("d MMM yyyy");Tickets.Insert(0,t);return t.Id;} }
